import re, json
keys=[k for k,_,_ in T]
assert len(keys)==len(set(keys)), [k for k in keys if keys.count(k)>1]
def esc(s): return json.dumps(s, ensure_ascii=False)
def emit(name, idx):
    lines=[f"// Generated by tools/i18n_table.py. Do not edit by hand.", ("export const en = {" if idx==1 else "import type { Messages } from \"./en\";\n\nexport const hi: Messages = {")]
    for row in T: lines.append(f"  {esc(row[0])}: {esc(row[idx])},")
    lines.append("};" if idx==2 else "} as const;")
    if idx==1: lines.append("\nexport type MessageKey = keyof typeof en;\nexport type Messages = Record<MessageKey, string>;")
    open(f"lib/i18n/{name}.ts","w").write("\n".join(lines)+"\n")
emit("en",1); emit("hi",2)
print(len(T),"messages")
